(() => {
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const money=n=>Number(n).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});let config=null,current=null,timer=null,busy=false;
async function api(action,body){const r=await fetch('/api/payments/'+action,{method:body?'POST':'GET',headers:{'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{}),signal:AbortSignal.timeout(22000)});let data;try{data=await r.json()}catch{throw Error('Pagamento temporariamente indisponível. Tente novamente mais tarde.')}if(!r.ok)throw Error(data.error||'Não foi possível consultar o pagamento.');return data}
const ready=api('config').then(c=>{config=c;return c}).catch(()=>{config={enabled:false,unavailable:true};return config});
function saved(){try{const a=JSON.parse(localStorage.getItem('purincash-orders')||'[]');return Array.isArray(a)?a:[]}catch{return []}}
function save(row){const rows=saved().filter(o=>o.id!==row.id);localStorage.setItem('purincash-orders',JSON.stringify([row,...rows].slice(0,100)))}
function pixScreen(row){current=row;const sandbox=row.environment==='sandbox';window.lojaCart.open('<div class="pc-payment"><span class="eyebrow">'+(sandbox?'PIX DE TESTE · SANDBOX':'PAGAMENTO PIX')+'</span><h2>'+(row.status==='pago'?'Pagamento confirmado':'Pague com PIX')+'</h2><p>'+esc(row.id)+'</p><strong class="pc-amount">'+money(row.total)+'</strong><div class="pc-status" id="pc-payment-status" role="status">'+(row.status==='pago'?'✓ Pagamento confirmado. A entrega dos itens será acompanhada separadamente.':sandbox?'Este PIX é de teste e não movimenta dinheiro.':'Aguardando pagamento. A confirmação é consultada na PurinCash.')+'</div>'+(row.status==='pendente'?((row.pix?.qrCodeImage?'<img class="pc-qr" src="'+esc(row.pix.qrCodeImage)+'" alt="QR Code PIX">':'')+'<label for="pc-code">PIX copia e cola</label><textarea id="pc-code" readonly>'+esc(row.pix?.brCode||'')+'</textarea><button class="button" data-pc-copy>Copiar código PIX</button><p class="pc-expiry">Válido até '+esc(new Date(row.expiresAt).toLocaleString('pt-BR'))+'</p><button class="pc-refresh" data-pc-refresh>Já paguei · verificar pagamento</button>'):'')+'<a class="pc-orders" href="/meus-pedidos">Ver meus pedidos →</a><p class="pc-note">Pagamento processado pela PurinCash. Pagamento confirmado não significa item entregue; a entrega não é automática nesta versão.</p></div>','payment');const heading=document.querySelector('.pc-payment h2');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true})}schedule()}
async function create(state){const data=await api('create',{email:state.email,username:state.username,items:state.items.map(({id,qty})=>({id,qty}))});const row={...data.order,token:data.token,pix:data.pix,expiresAt:data.expiresAt};try{save(row)}catch{}state.onConfirmed?.();pixScreen(row);return row}
async function check(row){const data=await api('status',{token:row.token});const updated={...row,status:data.status,paidAt:data.paidAt};try{save(updated)}catch{}return updated}
async function refresh(){if(!current||busy)return;const requested=current;busy=true;const status=document.querySelector('#pc-payment-status');try{const updated=await check(requested);if(current?.id!==requested.id||!document.querySelector('#modal')?.open||!document.querySelector('.pc-payment'))return;current=updated;if(current.status==='pago'){pixScreen(current)}else if(current.status==='expirado'||current.status==='reembolsado'){if(status)status.textContent=current.status==='expirado'?'Este PIX expirou.':'Pagamento reembolsado.';clearTimeout(timer)}else if(status)status.textContent='Pagamento ainda não confirmado. Aguarde e tente novamente.'}catch(e){if(status)status.textContent=e.message}finally{busy=false}}
function schedule(){clearTimeout(timer);if(current?.status==='pendente')timer=setTimeout(async()=>{if(document.querySelector('#modal')?.open&&document.querySelector('.pc-payment')){if(!document.hidden)await refresh();if(current?.status==='pendente')schedule()}},15000)}
async function mount(){await ready;document.querySelectorAll('.pdp-demo').forEach(el=>el.textContent=config.enabled?'Pagamento via PIX · entrega acompanhada separadamente':'Compra demonstrativa · sem cobrança ou entrega real');const note=document.querySelector('footer .fine');if(config.enabled&&note)note.textContent='Interface independente. Pagamentos via PurinCash. Entrega de produtos não automatizada nesta versão.';if(location.pathname==='/meus-pedidos'){const pending=saved().filter(o=>o.status==='pendente'||o.status==='pago').slice(0,5);await Promise.allSettled(pending.map(check));if(location.pathname==='/meus-pedidos')window.ordersPage?.refresh()}}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-pc-copy')){try{await navigator.clipboard.writeText(current.pix.brCode);b.textContent='Código copiado ✓'}catch{document.querySelector('#pc-code')?.select();b.textContent='Selecione e copie o código acima'}}if(b.hasAttribute('data-pc-refresh'))refresh();if(b.hasAttribute('data-pc-resume')){const row=saved().find(o=>o.id===b.dataset.pcResume);if(row){pixScreen(row);refresh()}}});
document.querySelector('#modal').addEventListener('close',()=>{clearTimeout(timer);current=null});window.paymentUI={ready,get unavailable(){return !!config?.unavailable||(!config?.enabled&&!['localhost','127.0.0.1','[::1]'].includes(location.hostname))},get enabled(){return !!config?.enabled},get environment(){return config?.environment},create,mount,saved};
})();
